package com.rubidiumclient.module.visualimport android.graphics.Canvasimport android.graphics.Colorimport android.graphics.Paintimport com.rubidiumclient.core.proxy.EntityTrackerimport com.rubidiumclient.core.proxy.EntityTracker.TrackedEntityimport com.rubidiumclient.module.BaseModuleimport com.rubidiumclient.module.ModuleCategoryimport com.rubidiumclient.module.social.isFriendEntityimport com.rubidiumclient.utils.MathUtilimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.Jobimport kotlinx.coroutines.SupervisorJobimport kotlinx.coroutines.currentCoroutineContextimport kotlinx.coroutines.delayimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.isActiveimport kotlinx.coroutines.launch/** * Tracks the nearest enemy and exposes it as a small immutable snapshot for * the draggable HUD box drawn by OverlayService, and also draws a tracer * line from screen center to that target on the full-screen ESP canvas. * * TargetHud used to be "EnemyESP", a full tracer/box/radar renderer for * every nearby entity. That's been narrowed to a single, focused job: decide * who the *current* target is, draw one clean tracer to them, and report * their name/health so OverlayService's draggable box can show it. The name * box (position, dragging, styling) still lives in OverlayService next to * the other HUD pieces (TotemCounterIcon, MenuFab, ...); this module only * owns the targeting logic and the tracer itself. */class TargetHud : BaseModule(    name = "TargetHud",    category = ModuleCategory.VISUAL,    description = "En yakın rakibi tracer ile gösterir, ismini taşınabilir bir kutuda listeler") {    companion object {        private const val TICK_INTERVAL_MS = 200L        const val CRITICAL_HEALTH = 5f    }    enum class TargetMode { Players, Hostiles, Both }    data class Target(        val name      : String,        val x         : Float,        val y         : Float,        val z         : Float,        val isPlayer  : Boolean,        val health    : Float,        val maxHealth : Float,        val distance  : Float    ) {        val isCritical: Boolean get() = health in 0f..CRITICAL_HEALTH    }    private val targetMode    = enum("Target Mode", TargetMode.Players)    private val scanRange     = float("Scan Range", 32f, 8f, 128f)    private val fov           = float("FOV", 70f, 30f, 130f)    private val ignoreFriends = bool("Ignore Friends", true)    private val showTracer    = bool("Show Tracer", true)    private val tracerWidth   = float("Tracer Width", 2.5f, 0.5f, 8f)    private val hudDispatcher = Dispatchers.Default    private val hudScope      = CoroutineScope(SupervisorJob() + hudDispatcher)    private var tickJob: Job? = null    private val _target = MutableStateFlow<Target?>(null)    val target: StateFlow<Target?> = _target.asStateFlow()    private val tracerPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {        style = Paint.Style.STROKE        strokeCap = Paint.Cap.ROUND    }    override fun onEnable() {        super.onEnable()        tickJob = hudScope.launch {            while (currentCoroutineContext().isActive) {                if (isEnabled) {                    _target.value = runCatching { resolveNearestTarget() }.getOrNull()                }                delay(TICK_INTERVAL_MS)            }        }    }    override fun onDisable() {        super.onDisable()        tickJob?.cancel()        tickJob = null        _target.value = null    }    private fun resolveNearestTarget(): Target? {        val range = scanRange.value        val candidates: Collection<TrackedEntity> = when (targetMode.value) {            TargetMode.Players  -> EntityTracker.getPlayers(range)            TargetMode.Hostiles -> EntityTracker.getHostiles(range)            TargetMode.Both     -> EntityTracker.getPlayers(range) + EntityTracker.getHostiles(range)        }        val nearest = candidates            .asSequence()            .filter { it.runtimeId != EntityTracker.selfRuntimeId }            .filterNot { ignoreFriends.value && it.isFriendEntity }            .minByOrNull { EntityTracker.distanceTo(it) }            ?: return null        return Target(            name      = nearest.name.ifBlank { nearest.identifier.removePrefix("minecraft:") },            x         = nearest.x, y = nearest.y, z = nearest.z,            isPlayer  = nearest.isPlayer,            health    = nearest.health,            maxHealth = nearest.maxHealth,            distance  = EntityTracker.distanceTo(nearest)        )    }    /**     * Draws a single tracer line from screen center to the current target,     * called every frame from ESPOverlayView alongside the other visual     * modules. Color follows the same "critical" logic as the HUD box: red     * once health drops below [CRITICAL_HEALTH], otherwise player/hostile     * tinted. No-ops silently if there's no target or it's off-screen.     */    fun render(canvas: Canvas, screenW: Int, screenH: Int) {        if (!isEnabled || !showTracer.value) return        val current = _target.value ?: return        val screenPos = MathUtil.worldToScreen(            current.x, current.y + 1.0f, current.z,            EntityTracker.selfX, EntityTracker.selfY, EntityTracker.selfZ,            EntityTracker.selfYaw, EntityTracker.selfPitch,            screenW, screenH,            fov.value        ) ?: return        val color = when {            current.isCritical -> Color.rgb(255, 69, 58)            current.isPlayer   -> Color.rgb(0, 200, 255)            else               -> Color.rgb(255, 152, 0)        }        tracerPaint.color = color        tracerPaint.strokeWidth = tracerWidth.value        canvas.drawLine(screenW / 2f, screenH / 2f, screenPos.first, screenPos.second, tracerPaint)    }}